export function nowIso() {
  return new Date().toISOString();
}

export function makeId(prefix: string) {
  return `${prefix}_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`;
}

export function getPageSource() {
  const icon =
    document.querySelector<HTMLLinkElement>('link[rel~="icon"]')?.href ||
    document.querySelector<HTMLLinkElement>('link[rel="apple-touch-icon"]')?.href ||
    `${window.location.origin}/favicon.ico`;
  const image =
    document.querySelector<HTMLMetaElement>('meta[property="og:image"]')?.content ||
    document.querySelector<HTMLMetaElement>('meta[name="twitter:image"]')?.content ||
    undefined;

  return {
    sourceUrl: window.location.href,
    pageTitle: document.title || "Untitled page",
    thumbnailUrl: image,
    faviconUrl: icon,
  };
}

export function domainFromUrl(url?: string) {
  if (!url) return "this page";
  try {
    return new URL(url).hostname.replace(/^www\./, "");
  } catch {
    return url.replace(/^https?:\/\//, "").split("/")[0] || "source";
  }
}

export function relativeTime(value?: string) {
  if (!value) return "just now";
  const diff = Date.now() - new Date(value).getTime();
  const minutes = Math.max(0, Math.round(diff / 60000));
  if (minutes < 1) return "just now";
  if (minutes < 60) return `${minutes}m ago`;
  const hours = Math.round(minutes / 60);
  if (hours < 24) return `${hours}h ago`;
  return `${Math.round(hours / 24)}d ago`;
}

export function formatBytes(bytes?: number) {
  if (!bytes) return "0 KB";
  const units = ["B", "KB", "MB", "GB"];
  let size = bytes;
  let unit = 0;
  while (size >= 1024 && unit < units.length - 1) {
    size /= 1024;
    unit += 1;
  }
  return `${size.toFixed(size >= 10 || unit === 0 ? 0 : 1)} ${units[unit]}`;
}
